package com.wizzadrds.theworldremembers.knowledge; import com.mojang.serialization.Codec; import com.mojang.serialization.codecs.RecordCodecBuilder; import net.minecraft.core.UUIDUtil; import java.util.UUID; public record ConversationRecord(UUID speaker,UUID listener,String eventId,long tick,boolean transferred){public static final Codec<ConversationRecord> CODEC=RecordCodecBuilder.create(i->i.group(UUIDUtil.CODEC.fieldOf("speaker").forGetter(ConversationRecord::speaker),UUIDUtil.CODEC.fieldOf("listener").forGetter(ConversationRecord::listener),Codec.STRING.fieldOf("eventId").forGetter(ConversationRecord::eventId),Codec.LONG.fieldOf("tick").forGetter(ConversationRecord::tick),Codec.BOOL.fieldOf("transferred").forGetter(ConversationRecord::transferred)).apply(i,ConversationRecord::new));}